'use strict';

// MODULES //

var isNegativeInteger = require( '@stdlib/math/base/assert/is-negative-integer' );
var gamma1pm1 = require( '@stdlib/math/base/special/gamma1pm1' );
var gammaln = require( '@stdlib/math/base/special/gammaln' );
var log1p = require( '@stdlib/math/base/special/log1p' );


// MAIN //

/**
* Evaluates the natural logarithm of the factorial of `x`.
*
* ## Method
*
* For \\(-1 < x < 2\\), forming \\(x+1\\) can round away low-order bits of \\(x\\), which results in large relative errors near the zeros of \\(\ln \Gamma(x+1)\\) at \\(x = 0\\) and \\(x = 1\\). To avoid forming \\(x+1\\), we use the identity
*
* ```tex
* \ln \Gamma(x+1) = \operatorname{log1p}(\Gamma(x+1) - 1) = \operatorname{log1p}(\operatorname{gamma1pm1}(x))
* ```
*
* @param {number} x - input value
* @returns {number} natural logarithm of factorial of `x`
*
* @example
* var v = factorialln( 3.0 );
* // returns ~1.792
*
* @example
* var v = factorialln( 2.4 );
* // returns ~1.092
*
* @example
* var v = factorialln( -1.0 );
* // returns NaN
*
* @example
* var v = factorialln( -1.5 );
* // returns ~1.266
*
* @example
* var v = factorialln( NaN );
* // returns NaN
*/
function factorialln( x ) {
	if ( isNegativeInteger( x ) ) {
		return NaN;
	}
	if ( x > -1.0 && x < 2.0 ) {
		return log1p( gamma1pm1( x ) );
	}
	return gammaln( x + 1.0 );
}


// EXPORTS //

module.exports = factorialln;
